typedef struct { char *base; int used; int max_sz; } _arr_arena_t;

static inline void *
_arr_arena_create(int max_sz) {
  _arr_arena_t *a;
  a = (void *)malloc(sizeof(_arr_arena_t));
  a->base = (char *)malloc(max_sz);
  a->used = 0;
  a->max_sz = max_sz;
  memset(a->base, 0, max_sz);
  return (void *)a;
}
